        static Time_Label(t, e) {
          if (t < 12) return 1 === t ? `${t} month` : `${t} months`;
          {
            const n = Math.floor(t / 12),
              i = t % 12;
            if (i > 0) {
              let t = "";
              return (
                (t +=
                  1 === n
                    ? e.useAbbreviatedFormat
                      ? `${n} yr,`
                      : `${n} year,`
                    : e.useAbbreviatedFormat
                    ? `${n} yrs,`
                    : `${n} years,`),
                (t +=
                  1 === i
                    ? e.useAbbreviatedFormat
                      ? ` ${i} mo`
                      : ` ${i} month`
                    : e.useAbbreviatedFormat
                    ? ` ${i} mos`
                    : ` ${i} months`),
                t
              );
            }
            return 1 === n ? `${n} year` : `${n} years`;
          }
        }
